  const UNSUPPORTED_FENCES = Object.freeze(["mermaid", "plantuml", "puml", "dot", "graphviz", "geojson", "topojson", "stl", "chart", "vega", "vega-lite", "flowchart", "sequence", "d2", "tikz"]);
