    info: ["info", "F10"],
    abstract: ["abstract", "F11"], summary: ["abstract", "F11"], tldr: ["abstract", "F11"],
    todo: ["todo", "F12"],
    success: ["success", "F13"], check: ["success", "F13"], done: ["success", "F13"],
