      let key = raw.length === 1 ? raw.toLowerCase() : raw;
      const code = String(e.code || "");
      if (/^Key[A-Z]$/.test(code)) key = code.slice(3).toLowerCase(); // same key on every layout
      else if (/^Digit[0-9]$/.test(code)) key = code.slice(5);
