        workOnly.checked = true;
        const allDayBusy = h("input", { type: "checkbox", "aria-label": "Count all-day events as busy" });
        allDayBusy.checked = false;
        const results = h("div", { class: "zn-cal-free-results", "aria-live": "polite" });
